import type { Logger } from '@cgp/config';
import type { ObjectStore } from '@cgp/contracts';
import { findStoryboard, outputs, scoped, type Database } from '@cgp/db';
import { findCompiledPrompt } from '@cgp/orchestration';
import { ffmpegAvailable, type FfmpegOptions } from '../render/ffmpeg';
import { buildReel, imageToClip, type ReelScene } from '../render/reel';
import type { JobHandler } from '../process';

/**
 * One board's scenes, joined into one video (WP68) — every scene already has its own clip,
 * generated by Omni or uploaded directly; this handler only stitches. No new model call, no new
 * moderation pass: each clip was already checked (generated) or is the creator's own upload.
 * Narration is already baked into each scene's own clip (Omni `generatesAudio: true`), so there
 * is no separate voice/captions pass here — a cross-scene captions track is a real feature, not
 * built in this pass.
 */
export const STORYBOARD_ASSEMBLE = 'storyboard_assemble';

/** 8s per scene is the app's one video atomic unit; an uploaded clip's real length is stored
 *  on the row instead, so this is only ever the fallback for a row written before that column. */
const DEFAULT_SCENE_SECONDS = 8;

export interface StoryboardAssembleHandlerDeps {
  db: Database;
  store: ObjectStore;
  ffmpeg: FfmpegOptions;
  logo?: (workspaceId: string) => Promise<{ data: Uint8Array; mimeType: string } | undefined>;
  providerLabel: string;
}

export function createStoryboardAssembleHandler(
  deps: StoryboardAssembleHandlerDeps,
): Record<string, JobHandler> {
  return {
    [STORYBOARD_ASSEMBLE]: async (job, log: Logger) => {
      const ws = scoped(deps.db, job.workspaceId);
      const settled = { actual: { credits: 0, videoSeconds: 0 } };
      const telemetry = {
        actionClass: STORYBOARD_ASSEMBLE,
        provider: deps.providerLabel,
        realisedCostInr: 0,
      };

      // Crash recovery: a retry after this already stored an output settles without redoing it.
      const [already] = await ws.select(outputs, { where: (t, op) => op.eq(t.jobId, job.id) });
      if (already) {
        log.info({ jobId: job.id }, 'storyboard already assembled, settling without rebuilding');
        return { ...settled, telemetry };
      }

      const input = job.input as { storyboardId?: unknown; compiledPromptId?: unknown };
      if (typeof input.storyboardId !== 'string') throw new Error('Job has no storyboard');
      if (typeof input.compiledPromptId !== 'string') throw new Error('Job has no compiled prompt');

      const board = await findStoryboard(deps.db, job.workspaceId, input.storyboardId);
      if (!board) throw new Error('Storyboard not found');
      if (board.scenes.length === 0) throw new Error('Storyboard has no scenes');

      const ordered = [...board.scenes].sort((a, b) => a.index - b.index);
      const missing = ordered.find((scene) => !scene.videoUrl && !scene.imageUrl);
      if (missing) throw new Error(`Scene ${missing.index + 1} has no clip yet`);

      if (!(await ffmpegAvailable(deps.ffmpeg))) {
        throw new Error('No renderer available to assemble the storyboard');
      }

      const scenes: ReelScene[] = [];
      for (const scene of ordered) {
        const durationSeconds = scene.videoDurationSeconds ?? DEFAULT_SCENE_SECONDS;
        if (scene.videoUrl) {
          const response = await fetch(scene.videoUrl);
          if (!response.ok) throw new Error(`Scene ${scene.index + 1}'s clip could not be fetched`);
          scenes.push({ data: new Uint8Array(await response.arrayBuffer()), durationSeconds });
        } else {
          // A still held for the scene's duration, not animated (WP69).
          const response = await fetch(scene.imageUrl!);
          if (!response.ok) throw new Error(`Scene ${scene.index + 1}'s image could not be fetched`);
          const image = new Uint8Array(await response.arrayBuffer());
          scenes.push(await imageToClip(deps.ffmpeg, image, durationSeconds, '720p-16:9'));
        }
      }

      const prompt = await findCompiledPrompt(deps.db, job.workspaceId, input.compiledPromptId);
      if (!prompt) throw new Error('Compiled prompt not found');

      const reel = await buildReel(deps.ffmpeg, {
        scenes,
        resolution: '720p-16:9',
        logo: await deps.logo?.(job.workspaceId),
      });

      const key = `${job.workspaceId}/storyboards/${board.id}/final.mp4`;
      const stored = await deps.store.put(key, reel.data, reel.mimeType);
      log.info(
        { storyboardId: board.id, seconds: reel.durationSeconds, scenes: scenes.length },
        'storyboard assembled',
      );

      const [output] = await ws.insert(outputs, {
        jobId: job.id,
        kind: 'video',
        storageKey: stored.key,
        metadata: {
          media: { url: stored.url, width: reel.width, height: reel.height },
          storyboardId: board.id,
          sceneCount: scenes.length,
        },
        compiledPromptId: prompt.id,
        templateId: prompt.templateId,
        brandKitVersion: prompt.brandKitVersion,
      });
      if (!output) throw new Error('Output insert returned no row');

      return { ...settled, telemetry };
    },
  };
}
